;jQuery(function() {
    "use strict";

    var $layout   = $('#adminLayout'),
        $sidebar  = $('#adminSidebar'),
        $toggler  = $('#sidebarToggler'),
        $overlay  = $('#sidebarOverlay');

    // 工具提示
    if ($('[data-bs-toggle="tooltip"]')[0]) {
        $('[data-bs-toggle="tooltip"]').tooltip({ "container": 'body' });
    }

    // 滚动条 - 侧边栏
    if ($('.admin-sidebar-nav')[0]) {
        new PerfectScrollbar('.admin-sidebar-nav', {
            swipeEasing: false,
            suppressScrollX: true
        });
    }

    // 侧边栏切换
    $toggler.on('click', function() {
        $layout.toggleClass('collapsed');
    });

    // 遮罩层点击关闭（移动端）
    $overlay.on('click', function() {
        $layout.removeClass('mobile-open');
    });

    // 移动端：点击侧边栏菜单项后自动关闭
    $(document).on('click', '.admin-sidebar-nav .nav-item a', function() {
        if (window.innerWidth < 992) {
            setTimeout(function() {
                $layout.removeClass('mobile-open');
            }, 150);
        }
    });

    /* ================================================================
       自定义标签页管理系统 (CTabs)
       完全替代 bootstrap-multitabs 插件
       ================================================================ */
    var CTabs = {
        tabs: {},           // { url: { url, title, $nav, $pane, $iframe, $loading, loaded } }
        order: [],          // 标签页顺序
        activeUrl: null,    // 当前激活的 URL
        mainUrl: null,      // 主页 URL（不可关闭）

        // 初始化
        init: function() {
            var self = this;
            var $default = $('#default-page');
            var defaultUrl = $default.attr('href') || 'dashboard.php';
            var defaultTitle = $default.find('span').text() || '首页';
            self.mainUrl = defaultUrl;

            // === 先绑定所有事件，再打开默认页 ===
            // 这样即使 open() 出错，按钮功能仍可用

            // 标签点击切换
            $(document).on('click', '.ct-tab-item', function(e) {
                if ($(e.target).hasClass('ct-tab-close') || $(e.target).closest('.ct-tab-close').length) return;
                var url = $(this).attr('data-url');
                self.activate(url);
            });

            // 关闭按钮（单个标签的 X）
            $(document).on('click', '.ct-tab-close', function(e) {
                e.preventDefault();
                e.stopImmediatePropagation();
                var url = $(this).closest('.ct-tab-item').attr('data-url');
                self.close(url);
            });

            // 侧边栏菜单点击
            $(document).on('click', '.ct-open-tab', function(e) {
                e.preventDefault();
                var url = $(this).attr('href');
                if (!url || url === 'javascript:void(0)') {
                    url = $(this).attr('data-url');
                }
                if (!url) return;
                var title = $(this).find('span').text() || $(this).text().trim() || url;
                self.open(url, title, true);
                self.updateSidebarActive(url);
            });

            // 刷新当前页
            $('#ctRefreshBtn').on('click', function(e) {
                e.preventDefault();
                if (self.activeUrl && self.tabs[self.activeUrl]) {
                    var tab = self.tabs[self.activeUrl];
                    tab.$loading.show();
                    tab.loaded = false;
                    tab.$iframe.attr('src', tab.url);
                }
            });

            // 关闭其他标签页（直接绑定，按钮在静态 HTML 中已存在）
            $('#ctCloseAllBtn').on('click', function(e) {
                e.preventDefault();
                self.closeOthers();
            });

            // 响应式
            $(window).on('resize', function() {
                if (window.innerWidth >= 992) {
                    $layout.removeClass('mobile-open');
                }
            });

            // 最后打开默认页
            self.open(defaultUrl, defaultTitle, true);
        },

        // 打开标签页
        open: function(url, title, active) {
            var self = this;
            if (self.tabs[url]) {
                if (active) {
                    self.activate(url);
                    self.updateSidebarActive(url);
                }
                return;
            }

            // 创建标签导航项
            var $navItem = $(
                '<li class="ct-tab-item" data-url="' + self.escapeAttr(url) + '">' +
                    '<span class="ct-tab-title">' + self.escapeHtml(title) + '</span>' +
                    '<i class="mdi mdi-close ct-tab-close"></i>' +
                '</li>'
            );
            $('#ctTabList').append($navItem);

            // 创建加载层
            var $loading = $(
                '<div class="ct-loading">' +
                    '<div class="ct-spinner"></div>' +
                    '<div class="ct-loading-text">加载中...</div>' +
                '</div>'
            );

            // 创建 iframe
            var $iframe = $('<iframe>', {
                src: url,
                frameborder: '0',
                allowtransparency: 'true',
                class: 'ct-iframe'
            });

            // 创建面板
            var $pane = $('<div class="ct-tab-pane" data-url="' + self.escapeAttr(url) + '"></div>');
            $pane.append($loading).append($iframe);
            $('#ctContent').append($pane);

            // 存储
            self.tabs[url] = {
                url: url,
                title: title,
                $nav: $navItem,
                $pane: $pane,
                $iframe: $iframe,
                $loading: $loading,
                loaded: false
            };
            self.order.push(url);

            // iframe 加载完成后隐藏 loading
            $iframe.on('load', function() {
                $loading.fadeOut(200);
                self.tabs[url].loaded = true;
            });

            if (active) {
                self.activate(url);
                self.updateSidebarActive(url);
            }

            self.scrollToTab($navItem);
        },

        // 激活标签页
        activate: function(url) {
            var self = this;
            if (!self.tabs[url]) return;

            $('.ct-tab-item').removeClass('active');
            $('.ct-tab-pane').removeClass('active');

            var tab = self.tabs[url];
            tab.$nav.addClass('active');
            tab.$pane.addClass('active');
            self.activeUrl = url;

            self.scrollToTab(tab.$nav);
        },

        // 关闭标签页
        close: function(url) {
            var self = this;
            if (!self.tabs[url]) return;
            if (url === self.mainUrl) return; // 主页不可关闭

            var idx = self.order.indexOf(url);
            var wasActive = (self.activeUrl === url);

            var tab = self.tabs[url];
            tab.$nav.remove();
            tab.$pane.remove();
            delete self.tabs[url];
            self.order.splice(idx, 1);

            if (wasActive && self.order.length > 0) {
                var newIdx = Math.min(idx, self.order.length - 1);
                var newUrl = self.order[newIdx];
                self.activate(newUrl);
                self.updateSidebarActive(newUrl);
            }
        },

        // 关闭其他标签页
        closeOthers: function() {
            var self = this;
            var toClose = [];
            for (var i = 0; i < self.order.length; i++) {
                if (self.order[i] !== self.mainUrl && self.order[i] !== self.activeUrl) {
                    toClose.push(self.order[i]);
                }
            }
            // 逐个关闭（倒序遍历，避免 splice 影响）
            for (var j = toClose.length - 1; j >= 0; j--) {
                self.close(toClose[j]);
            }
            // 视觉反馈
            var $btn = $('#ctCloseAllBtn');
            $btn.css('color', '#6d4aff');
            setTimeout(function() { $btn.css('color', ''); }, 300);
        },

        // 刷新标签页
        refresh: function(url) {
            var self = this;
            url = url || self.activeUrl;
            if (!self.tabs[url]) return;
            var tab = self.tabs[url];
            tab.$loading.show();
            tab.loaded = false;
            tab.$iframe.attr('src', tab.url);
        },

        // 更新侧边栏选中状态
        updateSidebarActive: function(url) {
            $('.nav-item').removeClass('active');
            $('.nav-item a[href="' + url + '"]').closest('.nav-item').addClass('active');
            // 处理 data-url 形式（下拉菜单中的链接）
            $('.nav-item a[data-url="' + url + '"]').closest('.nav-item').addClass('active');
        },

        // 滚动到标签页
        scrollToTab: function($tab) {
            var $nav = $('#ctTabNav');
            var tabLeft = $tab.position().left;
            var tabWidth = $tab.outerWidth(true);
            var viewLeft = $nav.scrollLeft();
            var viewRight = viewLeft + $nav.width();

            if (tabLeft < 0) {
                $nav.animate({ scrollLeft: viewLeft + tabLeft - 8 }, 200);
            } else if (tabLeft + tabWidth > $nav.width()) {
                $nav.animate({ scrollLeft: viewLeft + tabLeft + tabWidth - $nav.width() + 8 }, 200);
            }
        },

        // HTML 转义
        escapeHtml: function(text) {
            return $('<div>').text(text).html();
        },

        // 属性转义
        escapeAttr: function(text) {
            return String(text).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        },

        // 获取所有标签页
        getTabs: function() {
            var self = this;
            var list = [];
            for (var i = 0; i < self.order.length; i++) {
                var t = self.tabs[self.order[i]];
                if (t) {
                    list.push({
                        url: t.url,
                        title: t.title,
                        active: (self.activeUrl === t.url)
                    });
                }
            }
            return list;
        }
    };

    // 全局暴露，供 iframe 子页面调用
    window.CTabs = CTabs;

    // 初始化
    CTabs.init();

    // Cookie 主题（保留兼容）
    var the_site_theme = $.cookie('the_site_theme');
    if (the_site_theme) {
        // 迁移旧主题设置（不做实际切换）
    }
});
